/**
 * LessonConsultant
 *
 * Responsible for finding relevant lessons and formatting them for injection.
 * Called by the consult hook to provide context before Claude thinks.
 *
 * Features:
 * - Similarity threshold: Only inject highly relevant lessons
 * - Session deduplication: Don't re-inject lessons already in context
 */

import { getEmbedding, isReady, initializeEmbeddings } from '../embeddings/index.js';
import {
  searchLessonsByEmbeddingWithDistance,
  getCoreLessons,
  getInjectedLessonIds,
  recordInjectedLessons,
} from '../db/lessons.js';
import { lessonManager } from './LessonManager.js';
import type {
  Lesson,
  LessonCategory,
  ConsultOptions,
  ConsultResult,
} from './types.js';
import { LESSON_CATEGORY_NAMES } from './types.js';

// Default limits
const DEFAULT_MAX_SEMANTIC = 5;
const DEFAULT_MAX_CORE = 3;
const MAX_TOTAL_LESSONS = 8;

// Similarity thresholds (L2 distance - lower is more similar)
// Typical L2 distances for nomic-embed-text:
// - Very similar: < 0.5
// - Similar: 0.5 - 1.0
// - Somewhat related: 1.0 - 1.5
// - Unrelated: > 1.5
const SIMILARITY_THRESHOLD = 1.2; // Only include lessons with distance below this
const MIN_CONFIDENCE = 0.3; // Skip very low confidence lessons

export class LessonConsultant {
  /**
   * Consult lessons based on a prompt
   * Returns relevant lessons and formatted context for injection
   *
   * @param prompt - The user's prompt
   * @param projectPath - Current project path
   * @param options - Consultation options
   * @param sessionId - Claude session ID for deduplication (optional)
   */
  async consult(
    prompt: string,
    projectPath: string,
    options?: ConsultOptions,
    sessionId?: string
  ): Promise<ConsultResult> {
    const maxSemantic = options?.maxSemantic ?? DEFAULT_MAX_SEMANTIC;
    const maxCore = options?.maxCore ?? DEFAULT_MAX_CORE;

    // Get already-injected lessons for this session
    const alreadyInjected = sessionId ? getInjectedLessonIds(sessionId) : new Set<string>();

    // Ensure embeddings are ready
    if (!isReady()) {
      try {
        await initializeEmbeddings();
      } catch {
        // If embeddings fail, return core lessons only (filtered)
        const coreLessons = this.filterLessons(
          getCoreLessons(projectPath, maxCore),
          alreadyInjected
        );
        return this.buildResult(coreLessons, sessionId);
      }
    }

    // 1. Semantic search for relevant lessons with distance scores
    let semanticLessons: Lesson[] = [];
    try {
      const promptEmbedding = await getEmbedding(prompt);
      const results = searchLessonsByEmbeddingWithDistance(
        promptEmbedding,
        projectPath,
        maxSemantic * 2 // Fetch extra since we'll filter
      );

      // Filter by similarity threshold
      semanticLessons = results
        .filter(r => r.distance < SIMILARITY_THRESHOLD)
        .filter(r => r.lesson.confidence >= MIN_CONFIDENCE)
        .map(r => r.lesson);
    } catch {
      // Embedding search failed, continue with core lessons
    }

    // 2. Get core lessons (high confidence, frequently validated)
    const coreLessons = getCoreLessons(projectPath, maxCore);

    // 3. Merge and dedupe
    const allLessons = this.mergeAndRank([...semanticLessons, ...coreLessons]);

    // 4. Filter out already-injected lessons
    const newLessons = this.filterLessons(allLessons, alreadyInjected);

    // 5. Limit total
    const finalLessons = newLessons.slice(0, MAX_TOTAL_LESSONS);

    // 6. Record applications
    for (const lesson of finalLessons) {
      lessonManager.recordApplication(lesson.id);
    }

    return this.buildResult(finalLessons, sessionId);
  }

  /**
   * Quick consult without embeddings - just return core lessons
   */
  consultCore(
    projectPath: string,
    limit?: number,
    sessionId?: string
  ): ConsultResult {
    const alreadyInjected = sessionId ? getInjectedLessonIds(sessionId) : new Set<string>();

    const coreLessons = this.filterLessons(
      getCoreLessons(projectPath, limit ?? DEFAULT_MAX_CORE),
      alreadyInjected
    );

    // Record applications
    for (const lesson of coreLessons) {
      lessonManager.recordApplication(lesson.id);
    }

    return this.buildResult(coreLessons, sessionId);
  }

  /**
   * Filter out already-injected lessons
   */
  private filterLessons(lessons: Lesson[], alreadyInjected: Set<string>): Lesson[] {
    if (alreadyInjected.size === 0) {
      return lessons;
    }

    return lessons.filter(lesson => !alreadyInjected.has(lesson.id));
  }

  /**
   * Merge lessons and remove duplicates, ranking by relevance
   */
  private mergeAndRank(lessons: Lesson[]): Lesson[] {
    const seen = new Set<string>();
    const unique: Lesson[] = [];

    for (const lesson of lessons) {
      if (!seen.has(lesson.id)) {
        seen.add(lesson.id);
        unique.push(lesson);
      }
    }

    // Sort by confidence * validation score
    return unique.sort((a, b) => {
      const scoreA = a.confidence * (1 + a.timesValidated * 0.1);
      const scoreB = b.confidence * (1 + b.timesValidated * 0.1);
      return scoreB - scoreA;
    });
  }

  /**
   * Build the consult result with formatted context
   * Also records injections for session deduplication
   */
  private buildResult(lessons: Lesson[], sessionId?: string): ConsultResult {
    const formattedContext = this.formatForInjection(lessons);

    // Record which lessons were injected for this session
    if (sessionId && lessons.length > 0) {
      recordInjectedLessons(sessionId, lessons.map(l => l.id));
    }

    return { lessons, formattedContext };
  }

  /**
   * Format lessons for injection into Claude's context
   */
  private formatForInjection(lessons: Lesson[]): string {
    if (lessons.length === 0) {
      return '';
    }

    const lines: string[] = [
      '<project_knowledge>',
      'The following is established knowledge about this project.',
      '',
    ];

    // Group by category
    const byCategory = this.groupByCategory(lessons);

    for (const [category, categoryLessons] of Object.entries(byCategory)) {
      if (categoryLessons.length === 0) continue;

      const categoryName = LESSON_CATEGORY_NAMES[category as LessonCategory] || category;
      lines.push(`## ${categoryName}`);
      lines.push('');

      for (const lesson of categoryLessons) {
        lines.push(`### ${lesson.title}`);
        lines.push(lesson.insight);

        if (lesson.reasoning) {
          lines.push(`_Reason: ${lesson.reasoning}_`);
        }

        // Add confidence indicator for transparency
        if (lesson.confidence >= 0.8) {
          lines.push(`_(High confidence - validated ${lesson.timesValidated} times)_`);
        }

        lines.push('');
      }
    }

    lines.push('</project_knowledge>');

    return lines.join('\n');
  }

  /**
   * Group lessons by category
   */
  private groupByCategory(lessons: Lesson[]): Record<LessonCategory, Lesson[]> {
    const groups: Record<LessonCategory, Lesson[]> = {
      architecture_decision: [],
      anti_pattern: [],
      bug_pattern: [],
      project_convention: [],
      dependency_knowledge: [],
      domain_knowledge: [],
      workflow: [],
      other: [],
    };

    for (const lesson of lessons) {
      groups[lesson.category].push(lesson);
    }

    return groups;
  }
}

// Export a singleton instance
export const lessonConsultant = new LessonConsultant();
