/**
 * Lesson Consult Hook
 *
 * Called on UserPromptSubmit to inject relevant lessons before Claude thinks.
 * Searches for lessons relevant to the current prompt and formats them
 * as <project_knowledge> context for injection.
 */

import { lessonConsultant } from '../learning/LessonConsultant.js';

interface HookInput {
  prompt: string;
  cwd: string;
  session_id?: string;
}


/**
 * Read stdin as JSON
 */
async function readStdin(): Promise<string> {
  return new Promise((resolve) => {
    let data = '';
    process.stdin.setEncoding('utf8');
    process.stdin.on('readable', () => {
      let chunk;
      while ((chunk = process.stdin.read()) !== null) {
        data += chunk;
      }
    });
    process.stdin.on('end', () => {
      resolve(data);
    });
    // If no stdin data after timeout, resolve with empty
    setTimeout(() => resolve(data), 100);
  });
}

async function main() {
  try {
    const stdinData = await readStdin();
    if (!stdinData) {
      process.exit(0);
    }

    const input: HookInput = JSON.parse(stdinData);

    // Skip if no prompt or cwd
    if (!input.prompt || !input.cwd) {
      process.exit(0);
    }

    // Skip very short prompts (likely not worth consulting)
    if (input.prompt.length < 10) {
      process.exit(0);
    }

    // Consult lessons (pass session_id for deduplication)
    const { formattedContext } = await lessonConsultant.consult(
      input.prompt,
      input.cwd,
      {
        maxSemantic: 5,
        maxCore: 3,
      },
      input.session_id // Session ID for deduplication - don't re-inject same lessons
    );

    // Output context directly as plain text - Claude Code will inject it
    if (formattedContext) {
      console.log(formattedContext);
    }

    process.exit(0);
  } catch (error) {
    // Log error to stderr but don't block Claude
    console.error('Consult hook error:', error);
    process.exit(0);
  }
}

main();
